 $('dev-run').onclick=run(()=>{resultText(D.convertJSON($('dev-input').value,$('dev-format').value));message('Conversion ready.');});$('dev-example').onclick=()=>{$('dev-input').value=$('dev-format').value==='csv-json'?'name,score\nAda,42\nLin,37':'[{"name":"Ada","score":42,"active":true},{"name":"Lin","score":37,"active":false}]';$('dev-run').click();};$('dev-copy').onclick=()=>copy($('dev-output').value);$('dev-save').onclick=()=>{if(!$('dev-output').value)return;const ext={typescript:'ts',zod:'ts','json-csv':'csv','csv-json':'json'}[$('dev-format').value];download(new Blob([$ ('dev-output').value],{type:'text/plain;charset=utf-8'}),'converted.'+ext);};$('dev-format').onchange=()=>{resultText('');message('');};
