 $('tool').innerHTML=panel(`<div class="two-cols">${select('dev-from','Source game',games)}${select('dev-to','Target game',games)}${field('dev-sens','Source sensitivity','1','number','min="0" step="any"')}${field('dev-dpi','Source DPI','800','number','min="1"')}${field('dev-targetdpi','Target DPI','800','number','min="1"')}${field('dev-yaw1','Source yaw (degrees per count)','.022','number','min="0" step="any"')}${field('dev-yaw2','Target yaw (degrees per count)','.07','number','min="0" step="any"')}</div><p class="subtle">Preset yaw values are editable. Match physical movement, not FOV or zoom.</p>${actions(button('dev-run','Convert sensitivity',true,'key'))}<div id="dev-results"></div>`);
 $('dev-from').value='cs2';$('dev-to').value='valorant';$('dev-from').onchange=()=>{if(yaw[$('dev-from').value])$('dev-yaw1').value=yaw[$('dev-from').value];};$('dev-to').onchange=()=>{if(yaw[$('dev-to').value])$('dev-yaw2').value=yaw[$('dev-to').value];};$('dev-run').onclick=run(()=>{const r=D.sensitivity(num('dev-sens'),num('dev-dpi'),num('dev-targetdpi'),num('dev-yaw1'),num('dev-yaw2'));resultRows([['Target sensitivity',r.sensitivity.toFixed(6)],['Centimeters per 360°',r.cm360.toFixed(3)],['Source eDPI',r.edpi.toFixed(3)]]);});$('dev-run').click();
