EXTRA_TOOLS['meta-tag-preview']=()=>{
 $('tool').innerHTML=panel(field('dev-title','Page title','A thoughtful title for your next page')+area('dev-description','Page description','A useful description that explains what visitors can expect from this page.')+field('dev-url','Page URL','https://example.com/my-page')+field('dev-imageurl','Public image URL (optional)')+field('dev-image','Local preview image (optional)','','file','accept="image/*"')+actions(button('dev-run','Update previews',true,'spark'))+'<div class="output-section"><h3>Search preview</h3><div id="dev-searchpreview" data-no-i18n style="overflow-wrap:anywhere"></div><h3 style="margin-top:22px">Social preview</h3><img id="dev-socialimage" class="hidden" alt="" style="max-width:100%;max-height:220px;object-fit:cover"><div id="dev-socialpreview" data-no-i18n style="overflow-wrap:anywhere"></div><div id="dev-results"></div></div>'+area('dev-output','Metadata HTML','','readonly data-no-i18n')+actions(button('dev-copy','Copy result')));let imageURL;
 $('dev-image').onchange=()=>{if(imageURL)URL.revokeObjectURL(imageURL);const file=$('dev-image').files[0];if(file){imageURL=URL.createObjectURL(file);$('dev-socialimage').src=imageURL;$('dev-socialimage').classList.remove('hidden');}else{$('dev-socialimage').removeAttribute('src');$('dev-socialimage').classList.add('hidden');}};
 $('dev-run').onclick=run(()=>{const title=$('dev-title').value,description=$('dev-description').value,url=$('dev-url').value;resultText(D.meta(title,description,url,$('dev-imageurl').value.trim()));for(const id of ['dev-searchpreview','dev-socialpreview']){const root=$(id);root.replaceChildren();const address=document.createElement('small');address.textContent=new URL(url).hostname;const head=document.createElement('h3');head.textContent=title;head.style.color='#a54d2e';head.style.margin='8px 0';const desc=document.createElement('p');desc.textContent=description;root.append(address,head,desc);}let width=Array.from(title).length*9;try{const ctx=document.createElement('canvas').getContext('2d');if(ctx){ctx.font='20px Arial';width=ctx.measureText(title).width;}}catch{}resultRows([['Approximate title width (px)',Math.round(width)] ]);message('Previews updated. A local image is preview-only; host it and enter its public URL for metadata.');});$('dev-copy').onclick=()=>copy($('dev-output').value);$('dev-run').click();
};
EXTRA_TOOLS['regex-tester']=()=>{
 $('tool').innerHTML=panel(field('dev-pattern','Pattern','(?<word>\\w+)')+field('dev-flags','Flags','gu')+area('dev-input','Test text','Hello world, hello regex.')+actions(button('dev-run','Test expression',true,'code'))+area('dev-output','Matches and groups','','readonly data-no-i18n'));let worker=null,timer=null,generation=0;
 $('dev-run').onclick=run(()=>{assert(typeof Worker!=='undefined'&&URL.createObjectURL,'Worker support is required to safely run this test.');worker?.terminate();clearTimeout(timer);const current=++generation;const source='const assert=(ok,message)=>{if(!ok)throw Error(message)};const scan='+D.regexScan.toString()+';onmessage=e=>{try{postMessage({ok:true,result:scan(...e.data)})}catch(error){postMessage({ok:false,error:error.message})}}';const url=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));worker=new Worker(url);URL.revokeObjectURL(url);$('dev-run').disabled=true;resultText('');timer=setTimeout(()=>{worker?.terminate();$('dev-run').disabled=false;message('Expression exceeded the 1.5-second limit and was stopped.',true);},1500);worker.onmessage=e=>{if(current!==generation)return;clearTimeout(timer);worker.terminate();$('dev-run').disabled=false;if(e.data.ok){resultText(JSON.stringify(e.data.result,null,2));message('Test complete; output is capped at 2,000 matches.');}else message('Regular expression is invalid.',true);};worker.onerror=()=>{clearTimeout(timer);worker?.terminate();$('dev-run').disabled=false;message('Regular expression is invalid.',true);};worker.postMessage([$ ('dev-pattern').value,$('dev-flags').value,$('dev-input').value]);});for(const id of ['dev-pattern','dev-flags','dev-input'])$(id).addEventListener('input',()=>{generation++;worker?.terminate();clearTimeout(timer);$('dev-run').disabled=false;resultText('');message('');});window.addEventListener('pagehide',()=>{worker?.terminate();clearTimeout(timer);});
};
EXTRA_TOOLS['diff-checker']=()=>{
 $('tool').innerHTML=panel(`<div class="two-cols">${area('dev-a','Original text','one\ntwo\nthree')}${area('dev-b','Revised text','one\nchanged\nthree\nfour')}</div><div class="options">${check('dev-json','Normalize JSON')}${check('dev-case','Ignore case')}</div>`+actions(button('dev-run','Compare text',true,'code')+button('dev-save','Download patch'))+'<div id="dev-results"></div><h3 style="margin-top:22px">Line-by-line changes</h3><div id="dev-diff" data-no-i18n style="font:12px/1.8 monospace;white-space:pre-wrap;overflow-wrap:anywhere"></div>');let patch='';
 $('dev-run').onclick=run(()=>{let r;try{r=D.diff($('dev-a').value,$('dev-b').value,{json:$('dev-json').checked,ignoreCase:$('dev-case').checked});}catch{throw Error('Invalid JSON in one of the compared inputs.');}patch=r.patch;resultRows([['Added lines',r.added],['Removed lines',r.removed]]);$('dev-diff').replaceChildren();const wordChanges=new Map();for(let i=0;i<r.ops.length;i++){if(r.ops[i].type!=='-')continue;const removed=[];while(i<r.ops.length&&r.ops[i].type==='-')removed.push(r.ops[i++]);const added=[];while(i<r.ops.length&&r.ops[i].type==='+')added.push(r.ops[i++]);for(let j=0;j<Math.min(removed.length,added.length);j++){const words=D.wordDiff(removed[j].text,added[j].text);wordChanges.set(removed[j],words.a);wordChanges.set(added[j],words.b);}i--;}for(const op of r.ops){const line=document.createElement('div');line.append(document.createTextNode(op.type+' '));const words=wordChanges.get(op);if(words){for(const word of words){const span=document.createElement('span');span.textContent=word.text;if(word.changed){span.style.fontWeight='700';span.style.textDecoration=op.type==='-'?'line-through':'underline';}line.append(span);}}else line.append(document.createTextNode(op.text));if(op.type==='+')line.style.background='#f2e6d5';if(op.type==='-')line.style.background='#fae0dd';$('dev-diff').append(line);}message('Comparison ready.');});$('dev-save').onclick=()=>{if(patch)download(new Blob([patch],{type:'text/x-patch;charset=utf-8'}),'changes.patch');};$('dev-run').click();
};
EXTRA_TOOLS['jwt-decoder']=()=>{
 $('tool').innerHTML=panel(area('dev-token','Signed JWT')+actions(button('dev-decode','Decode token',true,'code'))+area('dev-header','Decoded header','','readonly data-no-i18n')+area('dev-claims','Decoded claims','','readonly data-no-i18n')+'<h3>Token status</h3><div id="dev-status"></div>'+select('dev-alg','Expected algorithm',['HS256','HS384','HS512','RS256','RS384','RS512','PS256','PS384','PS512','ES256','ES384','ES512'].map(x=>[x,x]))+area('dev-key','Verification key (secret, public JWK, or public PEM)')+actions(button('dev-verify','Verify signature',true,'key'))+'<p id="dev-signature" class="subtle">Signature not verified.</p>');let verifiedToken='';
 function decode(){const data=D.jwt($('dev-token').value);$('dev-header').value=JSON.stringify(data.header,null,2);$('dev-claims').value=JSON.stringify(data.payload,null,2);$('dev-status').replaceChildren();for(const text of data.warnings){const p=document.createElement('p');p.textContent=text;$('dev-status').append(p);}if(!data.warnings.length){const p=document.createElement('p');p.textContent='Decoded only. Claims are untrusted until signature and policy checks pass.';$('dev-status').append(p);}return data;}
 $('dev-decode').onclick=run(()=>{decode();message('Decoded only. Claims are untrusted until signature and policy checks pass.');});$('dev-verify').onclick=run(async()=>{const token=$('dev-token').value,algorithm=$('dev-alg').value,key=$('dev-key').value;decode();$('dev-verify').disabled=true;try{let valid;try{valid=await D.verifyJWT(token,key,algorithm);}catch(e){if(e.name==='DataError'||e.name==='OperationError'||e instanceof SyntaxError)throw Error('Verification failed. Check the key format and expected algorithm.');throw e;}if(token!==$('dev-token').value||key!==$('dev-key').value||algorithm!==$('dev-alg').value)return;verifiedToken=token;$('dev-signature').textContent=valid?'Signature verified. Check issuer, audience, expiry, and application policy separately.':'Signature is invalid.';message(valid?'Signature verified. Check issuer, audience, expiry, and application policy separately.':'Signature is invalid.',!valid);}finally{$('dev-verify').disabled=false;}});for(const id of ['dev-token','dev-key','dev-alg'])$(id).addEventListener('input',()=>{verifiedToken='';$('dev-signature').textContent='Signature not verified.';if(id==='dev-token'){$('dev-header').value='';$('dev-claims').value='';$('dev-status').replaceChildren();}message('');});
};
EXTRA_TOOLS['cron-explainer']=()=>{
 $('tool').innerHTML=panel(field('dev-cron','Cron expression','*/15 9-17 * * MON-FRI')+field('dev-zone','Time zone',Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC')+field('dev-after','Start after (UTC)',new Date().toISOString().slice(0,16),'datetime-local')+actions(button('dev-run','Explain schedule',true,'clock'))+'<div id="dev-results"></div><p class="subtle">Restricted day-of-month and weekday fields are combined with OR.</p><h3>Next ten runs</h3>'+area('dev-output','Result','','readonly data-no-i18n'));
 $('dev-run').onclick=run(()=>{const expression=$('dev-cron').value,zone=$('dev-zone').value.trim(),date=new Date($('dev-after').value+'Z'),parsed=D.cronParse(expression),times=D.cronNext(expression,zone,date,10);resultRows(['Minute','Hour','Day of month','Month','Weekday'].map((x,i)=>[x,[...parsed.sets[i]].sort((a,b)=>a-b).join(', ')]));resultText(times.map(t=>t.toISOString()+'  |  '+new Intl.DateTimeFormat(document.documentElement.lang==='fr'?'fr-FR':'en-GB',{timeZone:zone,dateStyle:'medium',timeStyle:'long'}).format(t)).join('\n'));message('Schedule calculated.');});
};
EXTRA_TOOLS['controller-tester']=()=>{
 $('tool').innerHTML=panel('<p class="subtle">Connect a controller, press a button, then start monitoring.</p>'+field('dev-threshold','Drift threshold','.10','number','min="0" max="1" step=".01"')+actions(button('dev-start','Start monitoring',true,'key')+button('dev-stop','Stop monitoring')+button('dev-drift','Measure resting drift'))+'<div id="dev-gamepads" class="output-section"></div><h3>Resting drift (RMS)</h3><div id="dev-results"></div><p id="dev-driftstatus" class="subtle">No measurement yet.</p>');
 let active=false,raf=null,lastRender=0,measureStart=0,measurements=new Map();
 const stop=()=>{active=false;if(raf!==null)cancelAnimationFrame(raf);raf=null;measureStart=0;$('dev-start').disabled=false;$('dev-drift').disabled=true;};
 const read=()=>{assert(typeof navigator.getGamepads==='function','Gamepad API unavailable. Try a recent browser in a secure context.');try{return Array.from(navigator.getGamepads()||[]).filter(Boolean);}catch{throw Error('Controller input is blocked by this browser context.');}};
 function render(pads){const root=$('dev-gamepads');root.replaceChildren();if(!pads.length){const p=document.createElement('p');p.textContent='No controller detected. Press a controller button to make it visible.';root.append(p);return;}for(const pad of pads){const title=document.createElement('h3');title.dataset.noI18n='';title.textContent=pad.id+' · #'+pad.index;root.append(title);const axesTitle=document.createElement('strong');axesTitle.textContent='Axes';root.append(axesTitle);const axes=document.createElement('div');axes.style.cssText='display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;margin:10px 0 20px';pad.axes.forEach((n,i)=>{const card=document.createElement('div');card.className='stat';const label=document.createElement('small');label.dataset.noI18n='';label.textContent='A'+i+'  '+n.toFixed(4);const bar=document.createElement('meter');bar.min=-1;bar.max=1;bar.value=n;bar.style.width='100%';FR_STRINGS['Axis '+i]='Axe '+i;bar.setAttribute('aria-label','Axis '+i);card.append(label,bar);axes.append(card);});root.append(axes);const bt=document.createElement('strong');bt.textContent='Buttons';root.append(bt);const buttons=document.createElement('div');buttons.style.cssText='display:flex;gap:6px;flex-wrap:wrap;margin:10px 0 25px';pad.buttons.forEach((b,i)=>{const cell=document.createElement('span');cell.className='pill';cell.dataset.noI18n='';cell.textContent='B'+i+': '+b.value.toFixed(2);cell.style.opacity=b.pressed?'1':'.45';buttons.append(cell);});root.append(buttons);}}
 function loop(time){if(!active)return;try{const pads=read();if(measureStart){for(const pad of pads){let entry=measurements.get(pad.index);if(!entry){entry={id:pad.id,sums:pad.axes.map(()=>0),count:0};measurements.set(pad.index,entry);}entry.count++;pad.axes.forEach((n,i)=>entry.sums[i]=(entry.sums[i]||0)+n*n);}if(time-measureStart>=3000){const rows=[];let above=0;for(const entry of measurements.values())entry.sums.slice(0,4).forEach((sum,i)=>{const rms=Math.sqrt(sum/entry.count);if(rms>num('dev-threshold'))above++;rows.push([entry.id+' · A'+i,rms.toFixed(5)]);});rows.push(['Drift threshold',num('dev-threshold')],['Axes above threshold',above]);resultRows(rows);measureStart=0;$('dev-driftstatus').textContent='Drift measurement complete.';message('Drift measurement complete.');}}
 if(time-lastRender>100){render(pads);lastRender=time;}raf=requestAnimationFrame(loop);}catch(e){stop();message(e.message,true);}}
 $('dev-start').onclick=run(()=>{read();if(active)return;active=true;$('dev-start').disabled=true;$('dev-drift').disabled=false;message('');raf=requestAnimationFrame(loop);});$('dev-stop').onclick=()=>{stop();message('Monitoring stopped.');};$('dev-drift').onclick=run(()=>{assert(num('dev-threshold')>=0&&num('dev-threshold')<=1,'Drift threshold must be between 0 and 1.');assert(read().length,'No controller detected. Press a controller button to make it visible.');measurements.clear();measureStart=performance.now();$('dev-driftstatus').textContent='Release the sticks and wait three seconds.';});$('dev-drift').disabled=true;window.addEventListener('pagehide',stop);
};
EXTRA_TOOLS['mouse-test']=()=>{
 $('tool').innerHTML=panel(select('dev-mode','Mouse test mode',[['cps','Click speed (5 seconds)'],['reaction','Reaction time'],['movement','Movement frequency (5 seconds)']])+field('dev-double','Double-click threshold (ms)','250','number','min="10" max="500"')+actions(button('dev-start','Start test',true,'clock'))+'<button id="dev-testarea" class="dropzone" type="button" style="width:100%;margin:22px 0;min-height:230px;touch-action:none">Click or move here</button><h3>Measured result</h3><div id="dev-results"></div><p class="subtle">Browser events only; this is not a hardware polling-rate guarantee.</p>');
 let mode='idle',start=0,lastClick=0,clicks=0,doubles=0,moves=0,seenTimes=new Set(),timer=null,readyTimer=null;const clear=()=>{clearTimeout(timer);clearTimeout(readyTimer);mode='idle';$('dev-testarea').style.background='';$('dev-start').disabled=false;};
 function finish(){const elapsed=(performance.now()-start)/1000;if(mode==='cps')resultRows([['Clicks',clicks],['Clicks per second',(clicks/elapsed).toFixed(2)],['Suspected double clicks',doubles]]);if(mode==='movement')resultRows([['Observed events per second',(moves/elapsed).toFixed(1)]]);clear();$('dev-testarea').textContent='Click or move here';message('Test complete.');}
 $('dev-start').onclick=run(()=>{clear();const threshold=num('dev-double');assert(Number.isFinite(threshold)&&threshold>=10&&threshold<=500,'Choose a valid double-click threshold from 10 to 500 ms.');mode=$('dev-mode').value;clicks=doubles=moves=0;lastClick=0;seenTimes.clear();$('dev-results').replaceChildren();message('');$('dev-start').disabled=true;if(mode==='reaction'){mode='waiting';$('dev-testarea').textContent='Wait for the signal…';const random=crypto.getRandomValues(new Uint32Array(1))[0]/0x100000000;readyTimer=setTimeout(()=>{mode='ready';start=performance.now();$('dev-testarea').textContent='Click now!';$('dev-testarea').style.background='#f5dfb9';},1200+random*2600);}else{start=performance.now();$('dev-testarea').textContent=mode==='cps'?'Click this area repeatedly.':'Move the mouse inside this area.';timer=setTimeout(finish,5000);}});
 $('dev-testarea').onclick=()=>{const now=performance.now();if(mode==='waiting'){clear();$('dev-testarea').textContent='Too early. Start again.';message('Too early. Start again.',true);}else if(mode==='ready'){resultRows([['Reaction (ms)',(now-start).toFixed(1)]]);clear();$('dev-testarea').textContent='Click or move here';message('Test complete.');}else if(mode==='cps'){clicks++;if(lastClick&&now-lastClick<num('dev-double'))doubles++;lastClick=now;resultRows([['Clicks',clicks],['Suspected double clicks',doubles]]);}};
 $('dev-testarea').addEventListener('pointermove',e=>{if(mode!=='movement')return;const events=e.getCoalescedEvents?.()||[e];for(const event of events){if(!seenTimes.has(event.timeStamp)){moves++;seenTimes.add(event.timeStamp);}}});$('dev-mode').onchange=()=>{clear();$('dev-testarea').textContent='Click or move here';message('');};window.addEventListener('pagehide',clear);
};
EXTRA_TOOLS['gta-6']=()=>{
 $('tool').innerHTML=panel('<p class="subtle">Unofficial fan tool. Original generated artwork; no official game assets.</p><p><a href="https://www.rockstargames.com/VI" target="_blank" rel="noopener noreferrer">Official release information</a></p>'+field('dev-launch','Launch date and time (local)','2026-11-19T00:00','datetime-local')+actions(button('dev-count','Update countdown',true,'clock'))+'<h3 style="margin-top:20px">Time until launch</h3><div id="dev-countdown" class="big-result" style="font-size:18px"></div>'+field('dev-seed','Crew name seed','Sunset')+actions(button('dev-names','Generate crew names'))+'<div id="dev-crews" class="output-section" data-no-i18n></div>'+field('dev-title','Wallpaper title','NIGHT SHIFT')+field('dev-subtitle','Overlay subtitle','Mission ready · Vice coast')+actions(button('dev-wallpaper','Create wallpaper',true,'image')+button('dev-overlay','Create transparent overlay'))+'<canvas id="dev-art" width="1280" height="720" class="hidden" style="width:100%;margin-top:20px;border-radius:9px"></canvas>'+actions(button('dev-save','Download PNG'))+'<h3 style="margin-top:25px">Launch-day checklist</h3><div class="field">'+['Check storage space','Install available updates','Charge controllers','Plan a comfortable play session'].map((x,i)=>'<div class="field">'+check('dev-task'+i,x)+'</div>').join('')+'</div>'+actions(button('dev-list','Download checklist')));
 let interval=null,artReady=false;function countdown(){const time=new Date($('dev-launch').value).getTime();assert(Number.isFinite(time),'Choose a valid launch date.');let left=Math.max(0,Math.floor((time-Date.now())/1000));if(!left){$('dev-countdown').textContent='Launch time reached.';return;}const values=[Math.floor(left/86400),Math.floor(left%86400/3600),Math.floor(left%3600/60),left%60],labels=['days','hours','minutes','seconds'];const root=$('dev-countdown');root.replaceChildren();values.forEach((v,i)=>{const wrap=document.createElement('span');const n=document.createElement('b');n.textContent=v;n.dataset.noI18n='';const label=document.createElement('span');label.textContent=' '+labels[i]+' ';wrap.append(n,label);root.append(wrap);});}
 $('dev-count').onclick=run(()=>{countdown();clearInterval(interval);interval=setInterval(()=>{try{countdown();}catch{clearInterval(interval);}},1000);});$('dev-names').onclick=()=>{const seed=$('dev-seed').value.trim()||'Sunset';const words=['Collective','Drivers','Night Crew','Coastline','Syndicate','Runners'];$('dev-crews').replaceChildren();for(const suffix of words){const p=document.createElement('p');p.textContent=seed+' '+suffix;$('dev-crews').append(p);}};
 function draw(overlay){const canvas=$('dev-art'),ctx=canvas.getContext('2d');assert(ctx,'Canvas is unavailable in this browser.');canvas.width=1280;canvas.height=overlay?220:720;ctx.clearRect(0,0,canvas.width,canvas.height);if(!overlay){const gradient=ctx.createLinearGradient(0,0,0,720);gradient.addColorStop(0,'#30233b');gradient.addColorStop(.6,'#c56b5b');gradient.addColorStop(1,'#efbd79');ctx.fillStyle=gradient;ctx.fillRect(0,0,1280,720);ctx.fillStyle='#f8ca88';ctx.beginPath();ctx.arc(940,260,100,0,Math.PI*2);ctx.fill();ctx.fillStyle='#241e2e';for(let i=0;i<32;i++){const height=70+(i*67%170);ctx.fillRect(i*42,720-height,37,height);ctx.fillStyle='#e9af73';for(let y=720-height+16;y<710;y+=20)if(i%3)ctx.fillRect(i*42+9,y,4,7);ctx.fillStyle='#241e2e';}ctx.fillStyle='#fff4df';ctx.font='bold 76px sans-serif';ctx.fillText($('dev-title').value.slice(0,24),70,200,1120);ctx.font='24px sans-serif';ctx.fillText($('dev-subtitle').value.slice(0,80),75,250,1100);}else{ctx.fillStyle='rgba(32,24,32,.82)';ctx.fillRect(25,25,1230,170);ctx.fillStyle='#df9e59';ctx.fillRect(25,25,9,170);ctx.fillStyle='#fff5e8';ctx.font='bold 52px sans-serif';ctx.fillText($('dev-title').value.slice(0,30),65,100,1150);ctx.font='26px sans-serif';ctx.fillText($('dev-subtitle').value.slice(0,80),65,155,1150);}canvas.classList.remove('hidden');artReady=true;message('Artwork ready.');}
 $('dev-wallpaper').onclick=run(()=>draw(false));$('dev-overlay').onclick=run(()=>draw(true));$('dev-save').onclick=()=>{if(artReady)$('dev-art').toBlob(blob=>{if(blob)download(blob,'launch-artwork.png');},'image/png');};$('dev-list').onclick=()=>{const lines=['Check storage space','Install available updates','Charge controllers','Plan a comfortable play session'].map((x,i)=>($('dev-task'+i).checked?'[x] ':'[ ] ')+(document.documentElement.lang==='fr'?FR_STRINGS[x]:x));download(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),'launch-checklist.txt');};countdown();$('dev-names').click();window.addEventListener('pagehide',()=>clearInterval(interval));
};
